#include <iostream>
#include <type_traits>

template <typename T>
struct Kind { static const int value = 0; };

template <typename T>
struct Kind<T*> { static const int value = 1; };

template <>
struct Kind<double> { static const int value = 2; };

int main() {
    int a = Kind<int>::value;
    int b = Kind<int*>::value;
    int c = Kind<double>::value;
    std::cout << a << b << c;
}
